import{z as l,x as o,o as s,c as d,q as r,j as i,D as t,d as e,s as n,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"分布式存储的案例","description":"","frontmatter":{"title":"分布式存储的案例","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/st-distributed-cases.md","filePath":"cs/st-distributed-cases.md","lastUpdated":1791413859000}'),C={name:"cs/st-distributed-cases.md"};function m(p,a,D,c,F,h){const B=o("Mermaid");return s(),d("div",null,[a[2]||(a[2]=r('<h1 id="分布式存储的案例" tabindex="-1">分布式存储的案例 <a class="header-anchor" href="#分布式存储的案例" aria-label="Permalink to &quot;分布式存储的案例&quot;">​</a></h1><div class="epigraph"><p>GFS、Dynamo、Bigtable、Spanner 回答的是同一份问卷：元数据谁管、数据怎么切、一致性卖到哪一级、失败假设是什么。四个答案互不相让，因为各自签的产品不同。</p><footer>—— 据 Ghemawat et al., SOSP 2003；DeCandia et al., SOSP 2007；Chang et al., OSDI 2006；Corbett et al., OSDI 2012 整理</footer></div><p><a href="/cs/st-cache-tiers">上一课</a>把单机栈的层次图拼完：页、日志、格式、缓存各归其位。机器多于一台时，这页纸要重新签。主干已钉过部分条款：<a href="/cs/distributed-fs-metadata">分布式文件与元数据</a>的元数据集中度、<a href="/cs/wide-column-bigtable">Bigtable</a> 的有序行键与列族、<a href="/cs/object-storage-s3">S3 对象存储语义</a>、<a href="/cs/storage-compute-separation">存算分离</a>。本课程倒数第二课读四个案例，把它们当同一份问卷的四份答卷来读：不是史实罗列，而是读出「取舍即产品定义」。后课收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>问卷四问。一问元数据：谁来回答「这段数据在哪」。二问切分：按范围还是按哈希，一片数据几个副本、谁主写。三问一致性：卖到最终一致还是外部一致，冲突留给谁。四问失败假设：组件按常坏设计还是按可信任设计。四问的答案组合就是产品：批处理为主的数据湖、购物车必须永远可写、万亿级行键扫描、全球金融级强一致，各自指向不同的组合。缺口是把这些组合放一张桌上对读，看每一家在哪一问上收、在哪一问上付。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>GFS 先答：单 master 把全部元数据放进内存，数据切成 64 MiB chunk 三副本，租约指定主副本；一致性只卖到「记录追加至少一次」，副本间可能不一致，散射与去重留给应用。付的是元数据服务的单点语义、收的是简单与吞吐——失败假设是组件常坏，检测比预防便宜。Dynamo 换卷：去中心，一致性哈希定环上位置，偏好列表放 \\(N\\) 副本，读写用松散仲裁 \\(R+W \\gt N\\)，向量时钟存版本、hinted handoff 兜节点故障、Merkle 树做反熵<span class="marginnote">数字实例：\\(N=3\\)、\\(R=2\\)、\\(W=2\\) 时 \\(R+W \\gt N\\) 成立，任一次读与任一次写至少在一个最新副本上相遇。把 \\(W\\) 降到 1，写永远成功，但读可能拿到旧版本——可用性买自一致性，账就记在这组参数里。</span>；一致性只卖最终一致，冲突合并交给客户端。收的是永远可写，付的是冲突语义外泄到业务层。<span class="marginnote">直觉类比：Merkle 树像先比目录再比章节的对账法——两副本先对哈希树根，不一致再往下钻一层，最后才定位到真正不同的那一小块，避免全量互抄一遍。</span>Bigtable 折中：tablet 按行键范围切、单点服务，位置表两级、根挂 Chubby，数据落 GFS；单行原子、批无跨行事务，收范围扫描的有序性。Spanner 加码：每个分片一组 Paxos，跨组两阶段提交，TrueTime 给时间戳加不确定区间，提交等到「时刻 \\(s\\) 确定已过去」才完成——外部一致是买来的，价格是每次提交等待 \\(\\epsilon\\)，以及部署 GPS 与原子钟的基础设施。<span class="marginnote">术语翻译：提交等待（commit wait）就是提交前先等过 TrueTime 报告的时钟不确定区间（毫秒级 \\(\\epsilon\\)），确认「提交时刻」在物理时间里确实已过去，外部一致才站得住。</span></p>',7)),(s(),i(A,null,{default:t(()=>[n(B,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%97%AE%E5%8D%B7%EF%BC%9A%E9%9C%80%E8%A6%81%E4%BB%80%E4%B9%88%E4%B8%80%E8%87%B4%E6%80%A7%EF%BC%9F%22%5D%20--%3E%7C%22%E5%A4%96%E9%83%A8%E4%B8%80%E8%87%B4%22%7C%20SP%5B%22Spanner%EF%BC%9APaxos%20%E7%BB%84%20%2B%20%E6%8F%90%E4%BA%A4%E7%AD%89%E5%BE%85%22%5D%0A%20%20Q%20--%3E%7C%22%E6%B0%B8%E8%BF%9C%E5%8F%AF%E5%86%99%22%7C%20DY%5B%22Dynamo%EF%BC%9A%E5%93%88%E5%B8%8C%E7%8E%AF%20%2B%20%E6%9D%BE%E6%95%A3%E4%BB%B2%E8%A3%81%22%5D%0A%20%20Q%20--%3E%7C%22%E8%8C%83%E5%9B%B4%E6%89%AB%E6%8F%8F%E5%90%9E%E5%90%90%22%7C%20BT%5B%22Bigtable%EF%BC%9A%E8%8C%83%E5%9B%B4%20tablet%20%2B%20%E5%8D%95%E7%82%B9%E6%9C%8D%E5%8A%A1%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%9E%E5%90%90%E4%BC%98%E5%85%88%EF%BC%8C%E5%BA%94%E7%94%A8%E5%85%9C%E5%BA%95%22%7C%20GF%5B%22GFS%EF%BC%9A%E5%8D%95%20master%20%2B%20%E7%A7%9F%E7%BA%A6%E5%89%AF%E6%9C%AC%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("四份答卷共享三个机制判断。其一，元数据集中度决定故障域与规模上限：GFS 的单 master 简单、但 master 的内存是 chunk 数量的天花板；Bigtable 的两级位置表把「谁服务这片」与「数据在哪」分开，是 "),E("a",{href:"/cs/storage-compute-separation"},"存算分离"),e("的雏形。其二，一致性级别与延迟直接挂钩：Spanner 的提交等待把时钟不确定度变成了每个事务的税，Dynamo 把仲裁降级成可用性，本质都是「一致性卖到哪级，延迟就在哪级收钱」。其三，副本数与冗余方式是失败假设的函数：GFS 时代顺序读为主，三副本够用；对象存储时代随机访问为主、容量便宜，纠删码接替三副本——"),E("a",{href:"/cs/object-storage-s3"},"S3 的语义课"),e("钉的正是这一步。案例读法至此成形：先问产品要什么，再倒推四问的答案，而不是相反。")],-1)),(s(),i(A,null,{default:t(()=>[n(B,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E5%86%99%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20DY%7B%22%E5%93%AA%E6%9D%A1%E5%86%99%E8%B7%AF%E5%BE%84%EF%BC%9F%22%7D%0A%20%20DY%20--%3E%7C%22Dynamo%EF%BC%9A%E6%B0%B8%E8%BF%9C%E5%8F%AF%E5%86%99%22%7C%20COOR%5B%22%E5%8D%8F%E8%B0%83%E8%80%85%E5%86%99%E5%81%8F%E5%A5%BD%E5%88%97%E8%A1%A8%20N%20%E5%89%AF%E6%9C%AC%22%5D%0A%20%20COOR%20--%3E%20Q%7B%22%E6%94%B6%E5%88%B0%20W%20%E4%B8%AA%E5%BA%94%E7%AD%94%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20RET%5B%22%E7%AB%8B%E5%8D%B3%E8%BF%94%E5%9B%9E%E6%88%90%E5%8A%9F%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%22%7C%20HH%5B%22hinted%20handoff%20%E6%9A%82%E5%AD%98%E5%86%8D%E8%A1%A5%22%5D%0A%20%20DY%20--%3E%7C%22Spanner%EF%BC%9A%E5%A4%96%E9%83%A8%E4%B8%80%E8%87%B4%22%7C%20PAX%5B%22%E5%88%86%E7%89%87%20Paxos%20%E7%BB%84%E5%A4%9A%E6%95%B0%E6%B4%BE%22%5D%0A%20%20PAX%20--%3E%20TT%5B%22TrueTime%20%E5%AE%9A%E6%8F%90%E4%BA%A4%E6%97%B6%E9%97%B4%E6%88%B3%22%5D%0A%20%20TT%20--%3E%20CW%5B%22%E6%8F%90%E4%BA%A4%E7%AD%89%E5%BE%85%20%CE%B5%20%E8%BF%87%E5%8E%BB%22%5D%0A%20%20CW%20--%3E%20RET2%5B%22%E6%8F%90%E4%BA%A4%E5%AE%8C%E6%88%90%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">数字锚点：GFS 的 64 MiB chunk 是为顺序扫描定的粒度，放到随机小读负载上就是元数据放大与热点；粒度是负载假设的化石——读案例先读它的失败假设。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重讲各系统内部：Bigtable 的 LSM tablet、S3 的语义、元数据层的做法各有专课；一致性理论的证明与 CAP 的推导不属本课；不写云厂商的现状对照。四个案例也不是终点：NewSQL、日志即数据库、湖仓一体都是问卷的新答卷，本课程把它们留给读法而不是罗列。下一课收束整门课程。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四问问卷：元数据归属、切分方式、一致性级别、失败假设；答案组合即产品定义。</li><li>GFS 卖吞吐留不一致给应用；Dynamo 卖可写把冲突外泄；Bigtable 卖范围有序；Spanner 买外部一致付提交等待。</li><li>元数据集中度决定故障域；GFS 单 master 与 Bigtable 位置表是两个极端的折中谱。</li><li>冗余方式随失败假设与负载演进：三副本到纠删码是负载假设变了。</li><li>出处：Ghemawat, Gobioff and Leung, SOSP 2003；DeCandia et al., SOSP 2007；Chang et al., OSDI 2006；Corbett et al., OSDI 2012。</li></ul>',5))])}const u=l(C,[["render",m]]);export{b as __pageData,u as default};
